// Источник: web-тест .qa/e2e/tests/guided-prayer/gp-08-no-recording-listen-disabled.spec.ts, план .qa/e2e/specs/guided-prayer.md (8.14), кейс .qa/tests/guided-prayer/GP-08-no-recording-listen-disabled.md
// Тикет #a5decf4a · a5decf4a9de744b22c38c93f. Опора: S-17 блок «האזן להקראה» (F-91).
// На 06.10 MP3 нет ни в одной из молитв ниже. Загрузит клиент — заменить молитву, это не баг.
import { expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabel, byLabelStartsWith, tapText, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { openPrayer, openRoute, hasDeepLinks } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

/** Блок «האזן להקראה»: «אין הקראה לקטע הזה», кнопка «השמע» неактивна. */
async function expectNoRecording() {
  await scrollToText('האזן להקראה');
  await expectVisibleText('האזן להקראה');
  await expect(byTextContains('אין הקראה לקטע הזה')).toBeDisplayed();
  const play = await byLabel('השמע');
  await expect(play).toBeDisplayed();
  expect(await play.isEnabled()).toBe(false);
}

async function switchNusach(title: string, to: 'ספרדי' | 'אשכנזי') {
  await (await byLabelStartsWith('בחירת נוסח')).click();
  await tapText(to);
  const replace = await byText('החלף');
  if (await replace.isDisplayed().catch(() => false)) await replace.click();
  await expectVisibleText(`${title} (${to})`);
}

describe('Молитва по шагам', () => {
  afterEach(async () => { await toHome(); });

  it('GP-08 Нет записи: «אין הקראה לקטע הזה», «השמע» неактивна — מנחה ספרד, שחרית אשכנז, ערבית אשכנז #a5decf4a @prod-safe', async () => {
    // 1. מנחה (ספרדי).
    if (hasDeepLinks()) await openRoute('/prayer/mincha_sfarad');
    else { await openPrayer('mincha_ashkenaz', 'מנחה'); await switchNusach('מנחה', 'ספרדי'); }
    await (await byTextMatches('\\d+ מתוך \\d+')).waitForDisplayed();
    await expectNoRecording();

    // Вернуть מנחה в נוסח профиля (из шапки — после возврата наверх через повторное открытие).
    if (!hasDeepLinks()) {
      await toHome();
      await openPrayer('mincha_ashkenaz', 'מנחה');
      if (await (await byText('מנחה (ספרדי)')).isDisplayed().catch(() => false)) await switchNusach('מנחה', 'אשכנזי');
    }

    // 2. שחרית (אשכנזי), ערבית (אשכנזי) — то же.
    for (const [key, title] of [['shacharit_ashkenaz', 'שחרית'], ['arvit_ashkenaz', 'ערבית']]) {
      await toHome();
      await openPrayer(key, title);
      await expectVisibleText(`${title} (אשכנזי)`);
      await expectNoRecording();
    }
  });
});
